import { listPrompts, getPrompt } from './server.mjs';

const checks = [];

async function expectThrow(fn, label) {
  try { await fn(); checks.push(label + ': NO THROW (FAIL)'); }
  catch (e) { checks.push(label + ': threw -> ' + e.message); }
}

// listPrompts
const lp = await listPrompts();
checks.push('listPrompts count: ' + lp.length + ', name: ' + lp[0].name + ', required args: ' + lp[0].arguments.map(a=>a.name+'='+a.required).join(','));

// happy path
const ok = await getPrompt('deploy_notice', { service: 'api', version: '1' });
checks.push('happy: messages=' + ok.messages.length + ', roles=' + ok.messages.map(m=>m.role).join(',') + ', textTypes=' + ok.messages.map(m=>m.content.type).join(','));

// missing
await expectThrow(() => getPrompt('deploy_notice', { version: '1' }), 'missing service');
await expectThrow(() => getPrompt('deploy_notice', { service: 'api' }), 'missing version');
await expectThrow(() => getPrompt('deploy_notice', {}), 'missing both');

// empty
await expectThrow(() => getPrompt('deploy_notice', { service: '', version: '1' }), 'empty service');
await expectThrow(() => getPrompt('deploy_notice', { service: 'api', version: '   ' }), 'whitespace version');

// extra
await expectThrow(() => getPrompt('deploy_notice', { service: 'api', version: '1', extra: 'x' }), 'extra arg');

// unknown
await expectThrow(() => getPrompt('other', { service: 'api', version: '1' }), 'unknown prompt');

console.log(checks.join('\n'));
""}

